328: /// Reads discovery messages from a single interface until discovery is stopped
329: /// or the socket keeps failing.
330: async fn receive_loop(
331:     socket: MulticastSocket,
332:     state: Arc<MulticastState>,
333:     event_tx: mpsc::Sender<MulticastEvent>,
334:     cancel: CancellationToken,
335: ) {
336:     let mut buffer = vec![0u8; RECEIVE_BUFFER_SIZE];
337:     let mut consecutive_errors = 0;
338: 
339:     loop {
340:         let received = tokio::select! {
341:             _ = cancel.cancelled() => return,
342:             received = socket.socket.recv_from(&mut buffer) => received,
343:         };
344: 
345:         let (size, source) = match received {
346:             Ok(received) => {
347:                 consecutive_errors = 0;
348:                 received
349:             }
350:             Err(err) => {
351:                 consecutive_errors += 1;
352:                 tracing::warn!(
353:                     "Could not receive multicast message on interface {}: {err:#}",
354:                     socket.description,
355:                 );
356:                 if consecutive_errors >= MAX_CONSECUTIVE_RECEIVE_ERRORS {
357:                     tracing::error!(
358:                         "Giving up on multicast interface {} after {consecutive_errors} consecutive errors",
359:                         socket.description,
360:                     );
361:                     return;
362:                 }
363:                 continue;
364:             }
365:         };
366: 
367:         let message = match serde_json::from_slice::<MulticastMessageV2>(&buffer[..size]) {
368:             Ok(message) => message,
369:             Err(err) => {
370:                 tracing::warn!("Could not parse multicast message from {source}: {err:#}");
371:                 continue;
372:             }
373:         };
374: 
375:         // Loopback is enabled, so our own messages come back as well.
376:         if message.fingerprint == state.device.fingerprint {
377:             continue;
378:         }
