380:         let event = MulticastEvent::Discovered {
381:             ip: source.ip(),
382:             scope_id: match &source {
383:                 SocketAddr::V6(source) if source.scope_id() != 0 => Some(source.scope_id()),
384:                 _ => None,
385:             },
386:             message,
