147: impl ServerHandle {
148:     /// The port the listeners are bound to. Relevant when the server was
149:     /// started with port 0, where the OS picks the port.
150:     pub fn port(&self) -> u16 {
151:         self.port
152:     }
153: 
154:     /// The socket addresses this server can be reached at: every address of
155:     /// the non-loopback interfaces, restricted to the address families that
156:     /// are actually bound. The listeners themselves only know the wildcard
157:     /// addresses, so the concrete addresses come from interface enumeration.
158:     ///
159:     /// Link-local IPv6 addresses are skipped: peers can only use them together
160:     /// with their own scope, which this device cannot know.
161:     ///
162:     /// Empty when the interfaces cannot be enumerated.
163:     pub fn local_addresses(&self) -> Vec<SocketAddr> {
164:         let Ok(interfaces) = if_addrs::get_if_addrs() else {
165:             return Vec::new();
166:         };
167:         let mut addresses: Vec<SocketAddr> = interfaces
168:             .into_iter()
169:             .filter(|interface| !interface.is_loopback())
170:             .filter_map(|interface| match interface.ip() {
171:                 IpAddr::V4(address) => Some(SocketAddr::new(address.into(), self.port)),
172:                 IpAddr::V6(address) if self.ipv6_bound && !address.is_unicast_link_local() => {
173:                     Some(SocketAddr::new(address.into(), self.port))
174:                 }
175:                 IpAddr::V6(_) => None,
176:             })
177:             .collect();
178:         addresses.sort();
179:         addresses.dedup();
180:         addresses
181:     }
