183:     /// Waits until the server task has terminated, the listeners are closed
184:     /// and all connections have been dropped, so that the port can be bound again.
185:     /// Must be called after requesting a stop via the stop channel.
186:     pub async fn wait_stopped(&self) {
187:         if let Some(task) = self.task.lock().await.take() {
188:             let _ = task.await;
189:         }
190:     }
191: 
192:     /// Cancels the active v2 upload session if it matches `session_id`,
193:     /// e.g. because the user aborted the transfer on the receiving side.
194:     ///
195:     /// Uploads that are already in progress still run to completion, but new
196:     /// upload requests fail and a new session can be created.
197:     /// No [ServerEventV2::SessionEnd] is emitted: the application initiated
198:     /// the cancellation itself.
199:     ///
200:     /// Returns `true` when a session was cancelled.
201:     pub async fn cancel_v2_session(&self, session_id: &str) -> bool {
202:         let Some(v2) = &self.v2 else {
203:             return false;
204:         };
205:         let mut slot = v2.session.lock().await;
206:         match slot.as_ref() {
207:             Some(SessionStateV2::Active(session)) if session.session_id == session_id => {
208:                 *slot = None;
209:                 true
210:             }
211:             _ => false,
212:         }
213:     }
214: }
