301: /// Binds an IPv6 listener with `IPV6_V6ONLY` enabled.
302: ///
303: /// Without this flag, some systems (e.g. macOS) bind IPv6 wildcard sockets in
304: /// dual-stack mode, which conflicts with the separate IPv4 listener on the same port.
305: fn bind_ipv6_only(socket_addr: SocketAddr) -> anyhow::Result<tokio::net::TcpListener> {
306:     let socket = socket2::Socket::new(
307:         socket2::Domain::IPV6,
308:         socket2::Type::STREAM,
309:         Some(socket2::Protocol::TCP),
310:     )?;
311:     socket.set_only_v6(true)?;
312:     #[cfg(not(windows))]
313:     socket.set_reuse_address(true)?;
314:     socket.set_nonblocking(true)?;
315:     socket.bind(&socket_addr.into())?;
316:     socket.listen(1024)?;
317:     Ok(tokio::net::TcpListener::from_std(socket.into())?)
318: }
