326: /// How long the accept loop waits after a failure that would repeat
327: /// immediately, doubling up to [`ACCEPT_BACKOFF_MAX`].
328: const ACCEPT_BACKOFF_MIN: std::time::Duration = std::time::Duration::from_millis(50);
329: const ACCEPT_BACKOFF_MAX: std::time::Duration = std::time::Duration::from_secs(1);
330: 
331: /// How many times in a row accepting may fail with a per-connection error
332: /// before the listener itself is considered broken. A healthy listener
333: /// interleaves such errors with successful accepts; only a dead one (e.g. a
334: /// socket the OS invalidated during app suspension, whose exact error code is
335: /// OS-specific) produces them in an endless, immediate sequence.
336: const ACCEPT_FAILURE_LIMIT: u32 = 100;
337: 
338: /// Detects peers that vanished without closing their connections (e.g. left
339: /// the network mid-transfer), which would otherwise count towards the
340: /// connection limits forever.
341: const TCP_KEEPALIVE: socket2::TcpKeepalive = socket2::TcpKeepalive::new()
342:     .with_time(std::time::Duration::from_secs(60))
343:     .with_interval(std::time::Duration::from_secs(10));
344: 
345: /// Whether the failed accept concerned only the connection being accepted, so
346: /// the next one can be attempted right away.
347: fn is_transient_accept_error(err: &std::io::Error) -> bool {
348:     matches!(
349:         err.kind(),
350:         std::io::ErrorKind::ConnectionAborted
351:             | std::io::ErrorKind::ConnectionReset
352:             | std::io::ErrorKind::Interrupted
353:     )
354: }
355: 
356: /// Whether the failed accept means the process momentarily ran out of
357: /// resources (a subnet scan opens a few hundred sockets), which resolves once
358: /// they are freed again.
359: fn is_resource_accept_error(err: &std::io::Error) -> bool {
360:     if err.kind() == std::io::ErrorKind::OutOfMemory {
361:         return true;
362:     }
363:     #[cfg(unix)]
364:     return matches!(
365:         err.raw_os_error(),
366:         Some(libc::EMFILE | libc::ENFILE | libc::ENOBUFS | libc::ENOMEM)
367:     );
368:     #[cfg(windows)]
369:     return matches!(
370:         err.raw_os_error(),
371:         Some(10024 /* WSAEMFILE */ | 10055 /* WSAENOBUFS */)
372:     );
373:     #[allow(unreachable_code)]
374:     false
375: }
