377: async fn start_server_with_listener(
378:     incoming: tokio::net::TcpListener,
379:     tls_config: Option<TlsConfig>,
380:     app_state: AppState,
381:     cancel: CancellationToken,
382:     connections: TaskTracker,
383: ) -> anyhow::Result<()> {
384:     // Browsers have no client certificate, so presenting one is optional while
385:     // the web pages are served. A certificate that is presented is still verified.
386:     let mandatory_client_auth = matches!(app_state.web.share, WebShare::Disabled);
387: 
388:     let tls_acceptor = match tls_config {
389:         Some(tls_config) => Some(
390:             create_tls_config(&tls_config, mandatory_client_auth).inspect_err(|err| {
391:                 tracing::error!("failed to create tls config: {err:#}");
392:             })?,
393:         ),
394:         None => None,
395:     };
396: 
397:     tracing::info!(
398:         "Started server on {} (TLS: {})",
399:         incoming.local_addr()?,
400:         tls_acceptor.is_some()
401:     );
402: 
403:     let mut accept_backoff = ACCEPT_BACKOFF_MIN;
404:     let mut accept_failures = 0u32;
405:     let mut at_connection_limit = false;
406:     loop {
407:         let (tcp_stream, remote_addr) = match incoming.accept().await {
408:             Ok(accepted) => {
409:                 accept_backoff = ACCEPT_BACKOFF_MIN;
410:                 accept_failures = 0;
411:                 // Disable Nagle: it delays small responses (reqwest already does this on the client side).
412:                 let _ = accepted.0.set_nodelay(true);
413:                 let _ = socket2::SockRef::from(&accepted.0).set_tcp_keepalive(&TCP_KEEPALIVE);
414:                 accepted
415:             }
416:             // Accepting fails for two kinds of reasons that say nothing about
417:             // the listener, which must both keep the loop alive: the peer went
418:             // away before the handshake completed (retried right away, but
419:             // bounded by [ACCEPT_FAILURE_LIMIT] because a listener the OS
420:             // invalidated during app suspension may report an OS-specific
421:             // error that looks per-connection), or the process momentarily ran
422:             // out of resources (a subnet scan opens a few hundred sockets).
423:             // Exhaustion would otherwise spin: the pending connection stays in
424:             // the backlog and fails again immediately, so back off before
425:             // retrying, without a limit — it says nothing about the listener,
426:             // however long it lasts.
427:             //
428:             // Every other error means the listening socket itself is broken.
429:             // Retrying that forever would leave the application believing it
430:             // can still receive, so give up and let the caller report it.
431:             Err(err) => {
432:                 if is_resource_accept_error(&err) {
433:                     tracing::warn!("Could not accept a connection: {err:#}");
434:                     tokio::time::sleep(accept_backoff).await;
435:                     accept_backoff = (accept_backoff * 2).min(ACCEPT_BACKOFF_MAX);
436:                     continue;
437:                 }
438:                 accept_failures += 1;
439:                 if is_transient_accept_error(&err) && accept_failures < ACCEPT_FAILURE_LIMIT {
440:                     tracing::warn!("Could not accept a connection: {err:#}");
441:                     continue;
442:                 }
443:                 return Err(anyhow::Error::from(err).context(format!(
444:                     "accepting connections failed {accept_failures} time(s) in a row"
445:                 )));
446:             }
447:         };
448: 
449:         // Dropping the stream closes the connection.
450:         let permit = match app_state.connection_limiter.try_acquire(remote_addr.ip()) {
451:             Ok(permit) => permit,
452:             Err(LimitReached::Total) => {
453:                 if !at_connection_limit {
454:                     tracing::warn!(
455:                         "Refusing connections: {MAX_CONNECTIONS} connections are being served"
456:                     );
457:                     at_connection_limit = true;
458:                 }
459:                 continue;
460:             }
461:             // Debug only: the peer decides how often this happens.
462:             Err(LimitReached::PerIp) => {
463:                 tracing::debug!(
464:                     "Refusing connection from {}: {MAX_CONNECTIONS_PER_IP} of its connections are being served",
465:                     remote_addr.ip()
466:                 );
467:                 continue;
468:             }
469:         };
470:         at_connection_limit = false;
471: 
472:         let tls_acceptor = tls_acceptor.clone();
473:         let app_state = app_state.clone();
474:         let cancel = cancel.clone();
475:         connections.spawn(async move {
476:             let _permit = permit;
477:             let serve = serve_connection(tcp_stream, remote_addr, tls_acceptor, app_state);
478:             tokio::select! {
479:                 _ = serve => {}
480:                 // Hard-drop the connection when the server is stopped.
481:                 _ = cancel.cancelled() => {}
482:             }
483:         });
484:     }
485: }
