487: async fn serve_connection(
488:     tcp_stream: tokio::net::TcpStream,
489:     remote_addr: SocketAddr,
490:     tls_acceptor: Option<tokio_rustls::TlsAcceptor>,
491:     app_state: AppState,
492: ) {
493:     let res = match tls_acceptor {
494:         Some(tls_acceptor) => {
495:             let tls_stream = match tls_acceptor.accept(tcp_stream).await {
496:                 Ok(tls_stream) => tls_stream,
497:                 Err(err) => {
498:                     tracing::warn!("TLS handshake error: {err:#}");
499:                     return;
500:                 }
501:             };
502: 
503:             let client_info = {
504:                 let (_, server_connection) = tls_stream.get_ref();
505:                 RequestClientInfo {
506:                     ip: PeerIp::from_remote_addr(&remote_addr),
507:                     // No certificate when client auth is optional (web pages served)
508:                     // and the client (e.g. a browser) did not present one.
509:                     cert: server_connection
510:                         .deref()
511:                         .deref()
512:                         .peer_certificates()
513:                         .and_then(|certs| certs.first().map(|cert| cert.to_vec())),
514:                 }
515:             };
516: 
517:             serve_http(tls_stream, client_info, app_state).await
518:         }
519:         None => {
520:             let client_info = RequestClientInfo {
521:                 ip: PeerIp::from_remote_addr(&remote_addr),
522:                 cert: None,
523:             };
524:             serve_http(tcp_stream, client_info, app_state).await
525:         }
526:     };
527: 
528:     if let Err(err) = res {
529:         tracing::warn!("Failed to serve connection: {err:#}");
530:     }
531: }
