533: /// Serves HTTP/1.1 only: HTTP/2 multiplexes many requests over one connection,
534: /// so the connection limits would no longer bound the requests of a peer.
535: async fn serve_http<I>(
536:     io: I,
537:     client_info: RequestClientInfo,
538:     app_state: AppState,
539: ) -> hyper::Result<()>
540: where
541:     I: AsyncRead + AsyncWrite + Unpin + Send + 'static,
542: {
543:     hyper::server::conn::http1::Builder::new()
544:         .serve_connection(
545:             TokioIo::new(io),
546:             hyper::service::service_fn(move |mut req: Request<Incoming>| {
547:                 req.extensions_mut()
548:                     .insert::<RequestClientInfo>(client_info.clone());
549:                 req.extensions_mut().insert::<AppState>(app_state.clone());
550:                 handle_request(req)
551:             }),
552:         )
553:         .await
554: }
