556: fn create_tls_config(
557:     tls_config: &TlsConfig,
558:     mandatory_client_auth: bool,
559: ) -> anyhow::Result<tokio_rustls::TlsAcceptor> {
560:     let config = {
561:         let certs = vec![CertificateDer::from_pem_slice(&tls_config.cert.as_bytes())?];
562:         let key = PrivateKeyDer::from_pem_slice(&tls_config.private_key.as_bytes())?;
563: 
