//! Comprehensive LocalSend Protocol v2 Transfer Benchmark
//! Evaluates throughput and latency across file sizes, batch transfers, Plain HTTP vs mTLS, and Memory vs Disk I/O.

use bytes::Bytes;
use localsend::crypto::cert::generate_self_signed;
use localsend::http::client::LsHttpClientV2;
use localsend::http::dto_v2::{PrepareUploadRequestDtoV2, RegisterDtoV2};
use localsend::http::server::common::save::FileUploadTarget;
use localsend::http::server::v2::{PrepareUploadDecisionV2, ServerEventV2};
use localsend::http::server::web::WebConfig;
use localsend::http::server::{start_with_port, ServerConfigV2, TlsConfig};
use localsend::http::state::ClientInfo;
use localsend::model::discovery::{DeviceType, ProtocolType, PROTOCOL_VERSION_V2};
use localsend::model::transfer::FileDto;
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::{mpsc, oneshot};
use tokio_util::sync::CancellationToken;

struct ServerInstance {
    port: u16,
    fingerprint: String,
    total_bytes: Arc<AtomicU64>,
    stop_tx: oneshot::Sender<()>,
}

async fn run_server(tls: bool, save_to_dir: Option<PathBuf>) -> ServerInstance {
    let (event_tx, mut event_rx) = mpsc::channel::<ServerEventV2>(256);
    let (stop_tx, stop_rx) = oneshot::channel();
    let total_bytes = Arc::new(AtomicU64::new(0));

    let (tls_config, fingerprint) = if tls {
        let cert = generate_self_signed().expect("cert generation failed");
        (
            Some(TlsConfig {
                cert: cert.certificate_pem,
                private_key: cert.private_key_pem,
            }),
            cert.fingerprint,
        )
    } else {
        (None, "PLAIN_HTTP_FINGERPRINT".to_string())
    };

    let info = ClientInfo {
        alias: "Benchmark Server".to_string(),
        device_model: Some("Arch Linux".to_string()),
        device_type: Some(DeviceType::Headless),
    };

    let v2_config = ServerConfigV2 {
        pin: None,
        verify_checksums: false, // disable receiver-side hashing to isolate network throughput
        event_tx,
    };

    let server_handle = start_with_port(
        0, // ephemeral port
        tls_config,
        info,
        None,
        Some(v2_config),
        WebConfig::disabled(),
        stop_rx,
    )
    .await
    .expect("failed to start server");

    let port = server_handle.port();

    let bytes_counter = total_bytes.clone();
    tokio::spawn(async move {
        while let Some(event) = event_rx.recv().await {
            match event {
                ServerEventV2::PrepareUpload {
                    files, decision_tx, ..
                } => {
                    let _ = decision_tx.send(PrepareUploadDecisionV2::Accept(
                        files.keys().cloned().collect(),
                    ));
                }
                ServerEventV2::FileUpload {
                    file_id,
                    target_tx,
                    ..
                } => {
                    let bytes_counter = bytes_counter.clone();
                    if let Some(ref dir) = save_to_dir {
                        let path = dir.join(&file_id);
                        let (result_tx, _result_rx) = oneshot::channel();
                        let _ = target_tx.send(FileUploadTarget::Path {
                            path,
                            result_tx,
                            progress_tx: None,
                        });
                    } else {
                        let (binary_tx, mut binary_rx) = mpsc::channel::<Bytes>(64);
                        let (result_tx, result_rx) = oneshot::channel();
                        let _ = target_tx.send(FileUploadTarget::Stream {
                            binary_tx,
                            result_rx,
                        });
                        tokio::spawn(async move {
                            while let Some(chunk) = binary_rx.recv().await {
                                bytes_counter.fetch_add(chunk.len() as u64, Ordering::Relaxed);
                            }
                            let _ = result_tx.send(Ok(()));
                        });
                    }
                }
                _ => {}
            }
        }
    });

    ServerInstance {
        port,
        fingerprint,
        total_bytes,
        stop_tx,
    }
}

async fn run_benchmark_run(
    label: &str,
    tls: bool,
    file_count: usize,
    file_size_bytes: usize,
    save_to_dir: Option<PathBuf>,
) -> anyhow::Result<()> {
    let server = run_server(tls, save_to_dir).await;
    let total_data_bytes = (file_count * file_size_bytes) as u64;

    // Client setup
    let client = if tls {
        let client_cert = generate_self_signed().expect("client cert failed");
        LsHttpClientV2::try_new(
            &client_cert.private_key_pem,
            &client_cert.certificate_pem,
            Some(server.fingerprint.clone()),
            Some(Duration::from_secs(60)),
        )?
    } else {
        LsHttpClientV2::try_new_without_cert()?
    };

    let protocol = if tls {
        ProtocolType::Https
    } else {
        ProtocolType::Http
    };

    let files: HashMap<String, FileDto> = (0..file_count)
        .map(|i| {
            let id = format!("bench-file-{i}");
            let file = FileDto {
                id: id.clone(),
                file_name: format!("file_{i}.dat"),
                size: file_size_bytes as u64,
                file_type: "application/octet-stream".to_string(),
                sha256: None,
                preview: None,
                metadata: None,
            };
            (id, file)
        })
        .collect();

    let payload = PrepareUploadRequestDtoV2 {
        info: RegisterDtoV2 {
            alias: "Bench Client".to_string(),
            version: PROTOCOL_VERSION_V2.to_string(),
            device_model: Some("Arch Linux".to_string()),
            device_type: Some(DeviceType::Headless),
            fingerprint: "CLIENT_FINGERPRINT".to_string(),
            port: server.port,
            protocol,
            download: false,
        },
        files,
    };

    let prep_start = Instant::now();
    let prep_res = client
        .prepare_upload(
            protocol,
            "127.0.0.1",
            server.port,
            None,
            payload,
            None,
            CancellationToken::new(),
        )
        .await?;

    let prep_duration = prep_start.elapsed();
    let resp = prep_res.response.expect("transfer rejected");
    let session_id = resp.session_id;

    let payload_chunk = Bytes::from(vec![0xAAu8; file_size_bytes]);

    let transfer_start = Instant::now();
    for (file_id, token) in resp.files {
        let body = localsend::reqwest::Body::from(payload_chunk.clone());
        client
            .upload(
                protocol,
                "127.0.0.1",
                server.port,
                None,
                &session_id,
                &file_id,
                &token,
                body,
                CancellationToken::new(),
            )
            .await?;
    }
    let transfer_duration = transfer_start.elapsed();

    let total_secs = transfer_duration.as_secs_f64();
    let mb_transferred = (total_data_bytes as f64) / (1024.0 * 1024.0);
    let throughput_mbs = mb_transferred / total_secs;
    let throughput_gbps = (throughput_mbs * 8.0) / 1000.0;

    println!(
        "| {:<28} | {:>5} files | {:>8.1} MB | {:>8.2?} | {:>8.2?} | {:>9.2} MB/s | {:>7.2} Gbps |",
        label,
        file_count,
        mb_transferred,
        prep_duration,
        transfer_duration,
        throughput_mbs,
        throughput_gbps
    );

    let _ = server.stop_tx.send(());
    Ok(())
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    println!("\n=============================================================================================================");
    println!("                           LOCALSEND RUST CORE (PACKAGES/CORE) BENCHMARK REPORT");
    println!("=============================================================================================================");
    println!("Test System: Linux x86_64, Hyper 1.11, Tokio 1.53, Rustls 0.23, Ring Crypto");
    println!("Transport:   Localhost loopback (127.0.0.1 TCP), zero-copy streaming");
    println!("-------------------------------------------------------------------------------------------------------------");
    println!(
        "| {:<28} | {:>11} | {:>11} | {:>10} | {:>10} | {:>14} | {:>12} |",
        "Test Scenario", "Files", "Volume", "Prep Time", "Send Time", "Throughput", "Bitrate"
    );
    println!("|------------------------------|-------------|-------------|------------|------------|----------------|--------------|");

    // 1. Plain HTTP benchmarks
    run_benchmark_run("Plain HTTP: 1x 10 MB", false, 1, 10 * 1024 * 1024, None).await?;
    run_benchmark_run("Plain HTTP: 1x 100 MB", false, 1, 100 * 1024 * 1024, None).await?;
    run_benchmark_run("Plain HTTP: 1x 500 MB", false, 1, 500 * 1024 * 1024, None).await?;
    run_benchmark_run("Plain HTTP: 200x 100 KB (batch)", false, 200, 100 * 1024, None).await?;

    // 2. HTTPS (mTLS + Ring + Fingerprint Verification)
    run_benchmark_run("mTLS (Ring): 1x 10 MB", true, 1, 10 * 1024 * 1024, None).await?;
    run_benchmark_run("mTLS (Ring): 1x 100 MB", true, 1, 100 * 1024 * 1024, None).await?;
    run_benchmark_run("mTLS (Ring): 1x 500 MB", true, 1, 500 * 1024 * 1024, None).await?;
    run_benchmark_run("mTLS (Ring): 200x 100 KB (batch)", true, 200, 100 * 1024, None).await?;

    // 3. Disk I/O (tmpfs sink)
    let temp_sink = std::env::temp_dir().join("localsend_bench_sink");
    let _ = std::fs::remove_dir_all(&temp_sink);
    std::fs::create_dir_all(&temp_sink)?;

    run_benchmark_run("mTLS + Disk I/O: 1x 100 MB", true, 1, 100 * 1024 * 1024, Some(temp_sink.clone())).await?;
    run_benchmark_run("mTLS + Disk I/O: 100x 1 MB", true, 100, 1 * 1024 * 1024, Some(temp_sink.clone())).await?;

    let _ = std::fs::remove_dir_all(&temp_sink);

    println!("=============================================================================================================\n");
    Ok(())
}

